-- Biblioteka e madhe e përrallave, pjesa 4 nga 5 (22 përralla).
-- Përralla më të gjata (8–15 minuta lexim): popullore shqiptare, klasike të rrëfyera (Grim, Andersen, Ezopi, Peroi,
-- Kipling, Kolodi, Kerolli, Baumi e të tjera, të gjitha të lira nga e drejta e autorit) dhe përralla origjinale të Bebix-it.
-- Secila ka ilustrimin e vet (cover_svg, i kontrolluar me pastruesin e app-it) dhe dalin në app pa përditësim.
-- I sigurt për t'u ekzekutuar dy herë: përrallat që ekzistojnë (sipas slug) nuk preken. Nuk fshin asgjë.
-- Kërkon migrimet 20261024090000_stories.sql dhe 20261025090000_story_drafts.sql (kolona cover_svg, source).

insert into public.stories (slug, language, title, summary, paragraphs, categories, age_min_months, age_max_months, reading_minutes, cover_key, cover_svg, status, featured, sort_order, source)
values
(
  $s$pata-me-veze-te-arta$s$, 'sq', $s$Pata me vezë të arta$s$,
  $s$Sipas Ezopit: një fshatar dhe gruaja e tij kanë një patë që bën çdo mëngjes një vezë prej ari. Por një vezë në ditë s'u mjafton më.$s$,
  array[
    $s$Në një fshat të vogël, në një shtëpi me çati të kuqe, jetonin një fshatar dhe gruaja e tij. Ishin të varfër, por punëtorë. Kishin një kopsht me perime, një lopë të vjetër dhe disa pata që shëtisnin nëpër oborr duke bërë ga-ga-ga.$s$,
    $s$Një mëngjes pranvere, gruaja shkoi në kotec të mblidhte vezët. Dhe aty, në kashtë, nën patën më të vogël e më të bardhë, gjeti diçka që shkëlqente si dielli. Ishte një vezë, por jo një vezë e zakonshme. Ishte e rëndë, e verdhë e shndritshme, e ftohtë në dorë. Ishte një vezë prej ari të pastër.$s$,
    $s$Gruaja vrapoi te burri. «Shiko, shiko!» Burri e mori vezën, e peshoi në dorë, e kafshoi lehtë me dhëmbë. «Është ar», pëshpëriti. «Ar i vërtetë!» E çuan te argjendari i qytetit, dhe ai u dha aq para, sa blenë një lopë të re, një thes miell dhe një palë këpucë për secilin.$s$,
    $s$Të nesërmen në mëngjes, pata e bardhë bëri përsëri një vezë ari. Dhe të pasnesërmen. Dhe çdo mëngjes, pa harruar asnjë ditë, një vezë të vetme, të artë e të shndritshme. Fshatari dhe gruaja e tij e quajtën Florina, dhe e donin shumë.$s$,
    $s$Kaluan muaj. Fshatari dhe gruaja e tij u bënë të pasur. Ndërtuan një shtëpi të re me dy kate. Blenë kuaj, dele e toka. Vishnin rroba të shtrenjta e hanin në pjata argjendi. Por me kalimin e kohës, ndodhi diçka e çuditshme: sa më shumë kishin, aq më pak u mjaftonte.$s$,
    $s$«Një vezë në ditë», tha një mbrëmje fshatari, duke numëruar arin. «Është shumë pak. Fqinji ynë, tregtari, ka dy shtëpi. Ne kemi vetëm një. Po sikur Florina të bënte dy vezë në ditë?» «Ose tri», tha gruaja. «Po t'i japim më shumë ushqim, ndoshta do të bëjë më shumë vezë.»$s$,
    $s$Të nesërmen, filluan ta ushqenin Florinën pesë herë në ditë. I jepnin grurë, misër, bukë, sa s'kishte më ku ta fuste. Pata e gjorë u bë aq e rëndë, sa mezi ecte. Por çdo mëngjes, bënte vetëm një vezë ari. As më shumë, as më pak.$s$,
    $s$«Ndoshta ka ftohtë», tha fshatari. Dhe i ndërtuan një kotec të veçantë, me mure të ngrohta e me derë të mbyllur, që të mos dilte më në oborr. Florina nuk shihte më diellin, nuk notonte më në pellg me patat e tjera, nuk gërmonte më barin. Dhe çdo mëngjes, bënte vetëm një vezë ari.$s$,
    $s$«Ajo po na i fsheh vezët», tha gruaja një ditë, me sy të ngushtuar. «Ndoshta brenda saj ka edhe shumë ar. Ndoshta është plot.» Dhe filluan ta ruanin ditë e natë, ta zgjonin në mes të natës për të parë mos kishte bërë vezë, ta shtynin, ta nxitonin. «Bëj vezë! Bëj vezë!» i thoshin. Florina dridhej nga frika.$s$,
    $s$Dhe një mëngjes, kur gruaja hyri në kotec, s'gjeti asgjë. As vezë ari, as vezë të zakonshme. Florina ishte ulur në një cep, e trishtuar, me pendët e fryra, dhe nuk bëri më vezë. As atë ditë, as të nesërmen, as një javë më pas. Florina ishte e lodhur, e trembur dhe e mërzitur, dhe ari brenda saj ishte shuar.$s$,
    $s$Fshatari dhe gruaja e tij u zemëruan, pastaj u trembën. Pa vezët e arta, paratë filluan të mbaronin. Shitën kuajt. Shitën delet. Shitën pjatat e argjendit. Dhe një natë, dera e kotecit mbeti e hapur nga harresa. Florina doli ngadalë në oborr, pa hënën për herë të parë pas shumë kohësh, hapi krahët dhe fluturoi larg, mbi pemë, drejt liqenit.$s$,
    $s$Fshatari dhe gruaja e tij mbetën vetëm me shtëpinë e madhe e bosh dhe me kopshtin e vjetër. Një mbrëmje, ulur në prag, gruaja tha me zë të ulët: «Kishim gjithçka. Një vezë ari në ditë, çdo ditë, pa punë, pa mundim. Dhe ne e humbëm, sepse donim më shumë, menjëherë.» Fshatari tundi kokën. «Lakmia na verboi», tha. «Dhe e trembëm krijesën që na kishte dhënë gjithçka.»$s$,
    $s$Që nga ajo ditë, fshatari dhe gruaja e tij u kthyen në punën e tyre. Mbollën kopshtin, kujdeseshin për lopën dhe ishin të lumtur me atë që kishin. Dhe thonë se ndonjëherë, në pranverë, një patë e bardhë ulej në pellgun pranë shtëpisë së tyre, notonte pak, i vështronte nga larg, dhe pastaj fluturonte përsëri drejt liqenit. Nuk bëri më kurrë vezë ari. Por fshatari dhe gruaja i hidhnin gjithmonë grurë, me mirënjohje, pa i kërkuar asgjë.$s$
  ]::text[],
