  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gpatamevezetearta" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#D3E8CB"/><stop offset="1" stop-color="#F4F7EA"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gpatamevezetearta)"/><circle cx="29.8" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="118" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="114" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="123" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 80.1Q40 75.8 80 87.8T160 81.1V120H0Z" fill="#B5D39A"/><path d="M0 101.9Q40 91.1 80 99.1T160 97.6V120H0Z" fill="#93BE7B"/><circle cx="47.6" cy="111.3" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="37.9" cy="112.2" r="1.6" fill="#E7B04B" opacity="0.9"/><circle cx="29" cy="113.4" r="1.6" fill="#E7B04B" opacity="0.9"/><circle cx="42.4" cy="109.2" r="1.6" fill="#E58C8A" opacity="0.9"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M6 44Q8 33 25 33L39 35Q45 35 43 29Q39 21 41 13Q43 7 49 9L55 13L49 14Q45 16 47 24Q53 40 39 48Q19 52 6 44Z" fill="#3E5A38"/><path d="M54 12L60 15L54 15.5Z" fill="#E58C5A"/><circle cx="48.5" cy="11.5" r="1" fill="#F4F7EA"/><path d="M16 38Q26 34 34 39Q24 43 16 38Z" fill="#F4F7EA" opacity="0.25"/><path d="M2 54Q14 51 26 54T52 54" fill="none" stroke="#F4F7EA" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/></g></svg>$s$,
