pse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><ellipse cx="28" cy="40" rx="18" ry="12" fill="#3F566E"/><circle cx="46" cy="30" r="9" fill="#3F566E"/><ellipse cx="56" cy="33" rx="5.5" ry="4" fill="#3F566E"/><circle cx="60.5" cy="32" r="1.7" fill="#F6F9FC"/><ellipse cx="41" cy="30" rx="4" ry="7" fill="#3F566E" transform="rotate(15 41 30)"/><circle cx="48" cy="27" r="1.2" fill="#F6F9FC"/><path d="M14 48L14 60M20 48L20 60M34 48L34 60M40 48L40 60" fill="none" stroke="#3F566E" stroke-width="4.5" stroke-linecap="round" stroke-linejoin="round"/><path d="M10 36Q2 30 6 22" fill="none" stroke="#3F566E" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
  'published', false, 940, 'editor'
