.2Q40 98.9 80 104.9T160 104.6V120H0Z" fill="#FFFFFF"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M22 56Q2 54 6 34Q8 18 22 14Q32 12 30 22Q20 22 18 32Q16 44 26 48Z" fill="#D9644A"/><ellipse cx="36" cy="46" rx="10" ry="12" fill="#3F566E"/><circle cx="42" cy="30" r="8" fill="#3F566E"/><path d="M38 24L40 15L44 23Z" fill="#3F566E"/><circle cx="45" cy="28" r="1.2" fill="#F6F9FC"/><ellipse cx="34" cy="58" rx="7" ry="2.5" fill="#3F566E"/><ellipse cx="46" cy="44" rx="3" ry="4" fill="#8A5A44"/></g></svg>$s$,
