104.4T160 99.4V120H0Z" fill="#FFFFFF"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M10 48L12 22L22 34L32 14L42 34L52 22L54 48Z" fill="#E7B04B"/><rect x="10" y="46" width="44" height="8" rx="2" fill="#E7B04B"/><circle cx="32" cy="14" r="3" fill="#D9644A"/><circle cx="12" cy="22" r="2.4" fill="#D9644A"/><circle cx="52" cy="22" r="2.4" fill="#D9644A"/><circle cx="22" cy="50" r="2" fill="#D9644A"/><circle cx="32" cy="50" r="2.2" fill="#4A9C9A"/><circle cx="42" cy="50" r="2" fill="#D9644A"/></g></svg>$s$,
