(
  $s$robot-toni$s$, 'sq', $s$Roboti Toni mëson të luajë$s$,
  $s$Toni është një robot i vogël që di të numërojë, të pastrojë e të rregullojë, por s'di të luajë. Sara e vogël i mëson gjënë më të vështirë për një robot: të bëjë diçka thjesht se është argëtuese.$s$,
  array[
    $s$Në shtëpinë e Sarës, një ditë, erdhi një kuti e madhe. Brenda ishte një robot i vogël, i argjendtë, sa një fëmijë tre vjeç, me dy sy të rrumbullakët që ndriçonin blu, me dy krahë që lëviznin e me rrota në vend të këmbëve. Babai e kishte marrë që të ndihmonte në shtëpi. Quhej Toni.$s$,
    $s$Toni dinte të bënte shumë gjëra. Dinte të numëronte deri në një milion. Dinte të fshinte dyshemenë, të palonte rrobat e të vendoste pjatat në raft, sipas madhësisë. Dinte motin e nesërm e emrat e të gjitha shteteve të botës. Dhe çdo gjë që bënte, e bënte në mënyrë të përsosur. «Detyra e përfunduar», thoshte pas çdo pune, me zërin e tij metalik.$s$,
    $s$Por Toni s'dinte të luante. Kur Sara ndërtoi një kështjellë me kube në dysheme, Toni i rregulloi të gjitha kubet sipas ngjyrës, në kutinë e tyre. «Rregulli i rikthyer», tha. Kur Sara vizatoi një diell vjollcë, Toni i tha: «Gabim. Dielli është i verdhë.» Dhe kur Sara u fsheh pas perdes për lojën e kukafshehtës, Toni tha: «Sara është pas perdes. Vendndodhja u gjet.» Dhe loja mbaroi menjëherë.$s$,
    $s$Sara u mërzit. «Toni», i tha, «a s'di të luash?» Sytë e Tonit pulsuan blu. «Të luash: veprim pa qëllim praktik. Nuk ka detyrë. Nuk ka përfundim. Nuk llogaritet.» «Pikërisht!» tha Sara. «Kjo është gjëja më e bukur e lojës!» Sytë e Tonit pulsuan më shpejt, sikur po mendonte shumë. «Nuk kuptoj», tha.$s$,
    $s$Sara vendosi t'i mësonte. «Mësimi i parë», i tha, «është të bësh diçka vetëm sepse të pëlqen.» E çoi në oborr, ku kishte një pellg të vogël nga shiu i natës. Sara kërceu në mes të pellgut, me çizmet e saj të kuqe, dhe uji spërkati kudo. Pastaj qeshi. «Provo», i tha Tonit. Toni e shikoi pellgun. «Uji do të më lagë rrotat», tha. «Pastaj do të duhet t'i thaj. Kjo është joefikase.» «Provo gjithsesi», tha Sara.$s$,
    $s$Toni u afrua ngadalë, dhe me rrotat e tij kaloi nëpër pellg. Spërk! Uji u hodh në ajër dhe ra mbi kokën e tij të argjendtë, në pika të vogla që shkëlqenin në diell. Toni ndaloi. Sytë e tij pulsuan, pastaj u bënë më të ndritshëm. «Kjo...», tha, «...kjo prodhoi një ndjesi të panjohur në qarqet e mia.» «Ky është gëzimi!» thirri Sara. «Bëje përsëri!» Spërk! Spërk! Spërk!$s$,
    $s$«Mësimi i dytë», tha Sara të nesërmen, «është imagjinata.» I dha Tonit një kuti të madhe kartoni. «Kjo është një anije kozmike», tha. Toni e skanoi. «Kjo është një kuti kartoni. Dimensionet: gjashtëdhjetë me dyzet centimetra.» «Jo», tha Sara. «Mbyll sytë.» Toni i errësoi sytë. «Tani, imagjino që kutia ka motorë, ka dritare me yje, ka një buton të kuq për nisjen. Dhe ne jemi brenda, duke fluturuar drejt Hënës.»$s$,
    $s$Toni heshti për një kohë të gjatë. Pastaj, shumë ngadalë, tha: «Numërimi mbrapsht para nisjes: dhjetë, nëntë, tetë...» Sara qeshi me gjithë zemër. Hynë të dy në kuti, dhe Toni bëri zhurmën e motorëve: vrrrrrr! Dhe fluturuan në Hënë, pastaj në Mars, pastaj në një planet të panjohur ku jetonin kafshë me tre sy. Toni shpiku emra për to. Ishin emra shumë të çuditshëm, me shumë numra. Por ishin të tijtë.$s$,
    $s$«Mësimi i tretë», tha Sara në ditën e tretë, «është më i vështiri. Është të humbasësh dhe të qeshësh.» Luajtën me zare. Toni, që mund ta llogariste gjithçka, fitonte çdo herë. «Toni», tha Sara, «nëse fiton gjithmonë, loja s'është argëtuese. Për asnjërin.» Toni u mendua. Pastaj, në lojën tjetër, nuk llogariti. Hodhi zarin si Sara, pa ditur ku do të binte. Dhe humbi.$s$,
    $s$Sytë e Tonit u bënë portokalli. «Kam humbur», tha. «Kjo është... e pakëndshme.» «E di», tha Sara. «Por shiko», dhe filloi të kërcente rreth tij me një vallëzim të çuditshëm fitoreje. Toni e shikoi. Pastaj, nga altoparlanti i tij, doli një zhurmë që s'e kishte bërë kurrë më parë: një seri tingujsh të shkurtër, si bip-bip-bip-bip. Toni po qeshte!$s$,
    $s$Pas atyre tri ditëve, Toni ndryshoi. Vazhdonte të ndihmonte në shtëpi, të palonte rrobat e të numëronte. Por tani, kur Sara ndërtonte kështjella, ai i shtonte një kullë të çuditshme, të shtrembër, vetëm sepse i pëlqente. Kur Sara vizatonte diell vjollcë, ai i shtonte një hënë jeshile. Dhe kur luanin kukafshehtas, Toni numëronte deri në dhjetë, ngadalë, dhe pastaj thoshte: «Ku mund të jetë Sara? Nuk e di!» edhe pse e dinte shumë mirë.$s$,
    $s$Një mbrëmje, ndërsa Sara po shkonte të flinte, Toni hyri në dhomën e saj. «Sara», tha, «kam një pyetje.» «Po?» «Pse më mësove të luaj? Nuk ishte e nevojshme për detyrat e mia.» Sara u mendua pak. «Sepse doja një shok», tha. «Dhe shokët luajnë bashkë.» Sytë e Tonit u bënë rozë, një ngjyrë që s'e kishin pasur kurrë më parë.$s$,
    $s$«Shok», tha Toni ngadalë, sikur po e provonte fjalën. «Ruajtur në kujtesën e përhershme.» Pastaj fiku dritën e madhe dhe ndezi sytë e tij në blu të butë, si një dritë nate. «Natën e mirë, Sara», tha. «Nesër, a luajmë përsëri me anijen kozmike?» «Patjetër», tha Sara me sy të mbyllur. Dhe Toni qëndroi pranë shtratit të saj gjithë natën, duke ndriçuar butë, si shokët që ruajnë njëri-tjetrin.$s$
  ]::text[],
  array['friendship']::text[], 36, 96, 11, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="grobottoni" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#F0E0CE"/><stop offset="1" stop-color="#F8EEE3"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#grobottoni)"/><rect x="112" y="14" width="34" height="40" rx="3" fill="#2E5566"/><path d="M122 23Q122 26 125 26Q122 26 122 29Q122 26 119 26Q122 26 122 23Z" fill="#F3EBD9"/><circle cx="136" cy="24" r="5" fill="#F3EBD9"/><path d="M129 14V54M112 34H146" fill="none" stroke="#F0E0CE" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><rect x="18" y="22" width="18" height="14" rx="1.5" fill="#E7D2BC"/><rect x="21" y="25" width="12" height="8" rx="1" fill="#A6CDB4"/><rect x="0" y="92" width="160" height="28" rx="0" fill="#DCC3A8"/><ellipse cx="80" cy="104" rx="50" ry="8" fill="#E7D2BC"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 35) scale(1.15)"><path d="M32 10V2" fill="none" stroke="#7A4E3A" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/><circle cx="32" cy="2" r="2.4" fill="#D9644A"/><rect x="18" y="10" width="28" height="20" rx="6" fill="#7A4E3A"/><circle cx="26" cy="20" r="4" fill="#F8EEE3"/><circle cx="38" cy="20" r="4" fill="#F8EEE3"/><circle cx="26" cy="20" r="2" fill="#7FB8C6"/><circle cx="38" cy="20" r="2" fill="#7FB8C6"/><rect x="14" y="32" width="36" height="20" rx="5" fill="#7A4E3A"/><circle cx="32" cy="42" r="4" fill="#D9644A"/><path d="M14 38L6 46M50 38L58 30" fill="none" stroke="#7A4E3A" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="22" cy="56" r="4" fill="#F8EEE3"/><circle cx="42" cy="56" r="4" fill="#F8EEE3"/><circle cx="22" cy="56" r="4" fill="#7A4E3A" opacity="0"/></g></svg>$s$,
  'published', false, 1010, 'editor'
),
(
  $s$pinoku$s$, 'sq', $s$Pinoku$s$,
  $s$Sipas Karlo Kolodit: xhaxha Xhepeto gdhend një kukull prej druri që flet, vrapon dhe bën shumë prapësira. Pinoku duhet të mësojë të jetë i sinqertë dhe i mirë para se të bëhet djalë i vërtetë.$s$,
  array[
    $s$Na ishte një herë... «Një mbret!» do të thonë menjëherë lexuesit e mi të vegjël. Jo, fëmijë, nuk e keni qëlluar. Na ishte një herë një copë dru. Nuk ishte dru i çmuar, por një copë e thjeshtë, nga ato që hidhen në sobë dimrit. Dhe kjo copë dru përfundoi në punishten e një plaku që quhej Xhepeto.$s$,
    $s$Xhepeto ishte një marangoz i varfër e i vetmuar. Jetonte në një dhomë të vogël, me një sobë të vizatuar në mur, sepse s'kishte para për një të vërtetë. «Do të gdhend një kukull prej druri», tha. «Një kukull që di të kërcejë e të bëjë kapërcime. Do të udhëtoj me të nëpër botë, dhe kështu do të fitoj një copë bukë.» Dhe e quajti Pinoko.$s$,
    $s$Por sapo i gdhendi sytë, sytë e kukullës lëvizën dhe e shikuan. Sapo i gdhendi hundën, hunda filloi të rritej. Sapo i gdhendi gojën, goja filloi të qeshte. Dhe sapo i gdhendi këmbët, Pinoku kërceu nga tryeza dhe vrapoi nga dera, nëpër rrugë, me Xhepeton që i vraponte pas.$s$,
    $s$Xhepeto e donte Pinokun si birin e tij. Shiti xhaketën e vetme që kishte, në mes të dimrit, që t'i blinte një libër abetareje. «Shko në shkollë», i tha, «dhe mëso, që të bëhesh i zgjuar e i mirë.» Pinoku u nis me librin nën krah, i vendosur të ishte nxënësi më i mirë. Por në rrugë dëgjoi muzikë daullesh dhe flautash. Ishte teatri i kukullave. Dhe Pinoku shiti abetaren për të blerë një biletë.$s$,
    $s$Kështu filluan aventurat e Pinokut. Kudo që shkonte, i premtonte vetes të ishte i mirë, dhe pastaj, në kthesën e parë, ndiqte çfarë i dukej më argëtuese. Në teatër, kukullat e tjera e njohën si vëlla. Pronari i teatrit, një burrë i madh me mjekër të zezë, deshi ta hidhte në zjarr. Por Pinoku i foli për Xhepeton e varfër, dhe burri i madh, që kishte zemër më të butë se ç'dukej, teshtiu nga mallëngjimi dhe i dha pesë monedha ari për babanë e tij.$s$,
    $s$Në rrugë për në shtëpi, Pinoku takoi një dhelpër që çalonte e një mace që bëhej e verbër. «Ku po shkon me ato monedha?» e pyetën. «Po t'i mbjellësh në Fushën e Mrekullive», i thanë, «nga çdo monedhë do të rritet një pemë me mijëra monedha.» Pinoku i besoi. Natën, i mbolli monedhat dhe shkoi të flinte. Në mëngjes, fusha ishte bosh, dhe dhelpra e maca ishin zhdukur, bashkë me monedhat.$s$,
    $s$Në pyll, Pinoku takoi Zanën me flokë të kaltër, një zanë e bukur që jetonte në një shtëpi të bardhë. Ajo e pyeti ku i kishte monedhat. «I humba», gënjeu Pinoku, dhe sapo e tha, hunda iu zgjat dy gisht. «Ku i humbe?» «Në pyll», gënjeu përsëri, dhe hunda iu zgjat edhe më shumë. «Mos vallë i ke në xhep?» Dhe Pinoku gënjeu për të tretën herë, dhe hunda iu rrit aq shumë, sa s'mund të kthehej më në dhomë. Zana qeshi. «Gënjeshtrat njihen menjëherë», i tha. «Disa kanë këmbë të shkurtra, të tjerat kanë hundë të gjatë.»$s$,
    $s$Pinoku qau aq shumë, sa zana i dërgoi një mijë qukapikë, që ia çukitën hundën derisa u bë sa ishte. «Do të jem i mirë tani», premtoi Pinoku. «Do të shkoj në shkollë.» Dhe për një kohë, shkoi. Mësoi të lexonte e të shkruante. Por pastaj, një shok i tij, Fitili, i foli për një vend të mrekullueshëm, Vendin e Lodrave, ku s'kishte shkollë, ku gjithë ditën luhej, dhe ku e enjtja e e diela ishin çdo ditë.$s$,
    $s$Pinoku shkoi. Dhe për pesë muaj luajti pa pushim, në Vendin e Lodrave, ku s'kishte libra e s'kishte mësues. Por një mëngjes, kur u zgjua, iu duk se kishte diçka në kokë. Shikoi në pasqyrë: i ishin rritur dy veshë të gjatë gomari. Pastaj iu rrit bishti. Pastaj filloi të pëllinte: i-a, i-a! Të gjithë fëmijët e Vendit të Lodrave ishin bërë gomarë, sepse kështu ndodh me ata që s'duan të mësojnë asgjë.$s$,
    $s$Gomarin Pinoko e shitën në një cirk, ku duhej të kërcente nëpër rrathë. Një ditë u rrëzua, u çalua, dhe pronari e hodhi në det. Por në ujë, peshqit e zanës e lëpinë dhe ia hoqën lëkurën e gomarit, dhe Pinoku u bë përsëri kukull prej druri. Ishte i lumtur, deri sa pa një peshkaqen të madh, sa një pallat me tri kate, që hapi gojën dhe e gëlltiti të tërin.$s$,
    $s$Brenda barkut të peshkaqenit ishte errësirë. Por larg, në thellësi, Pinoku pa një dritë të vogël. Shkoi drejt saj dhe gjeti, ulur pranë një tryeze me një qiri, një plak me flokë të bardha. Ishte Xhepeto! Kishte dalë me varkë në det për të kërkuar Pinokun, dhe peshkaqeni e kishte gëlltitur, me varkë e me gjithçka, dy vjet më parë.$s$,
    $s$«Babi!» thirri Pinoku dhe e përqafoi. «Kurrë më s'do të largohem nga ti!» Atë natë, ndërsa peshkaqeni flinte me gojë hapur, sepse vuante nga astma, Pinoku mori Xhepeton në shpinë dhe notoi jashtë, nëpër dhëmbët e mëdhenj, nën dritën e hënës, deri në breg. Xhepeto ishte i dobët e i sëmurë. Dhe Pinoku, për herë të parë në jetën e tij, vendosi të punonte.$s$,
    $s$Çdo ditë, Pinoku nxirrte ujë nga pusi i një fermeri, njëqind kova, për një gotë qumësht për babanë. Natën, thurte shporta me kallama, për t'i shitur. Mësoi të lexonte në dritën e qiririt. Dhe kur kishte pak para të tepërta, i çonte për Zanën me flokë të kaltër, që kishte dëgjuar se ishte e sëmurë. Kështu kaluan pesë muaj, dhe Pinoku nuk tha asnjë gënjeshtër.$s$,
    $s$Një natë, Pinoku pa në ëndërr Zanën, që i buzëqeshte dhe i thoshte: «Bravo, Pinoko. Për zemrën tënde të mirë, të fal të gjitha prapësirat. Fëmijët që kujdesen me dashuri për prindërit e tyre meritojnë lavdërim dhe dashuri.» Dhe kur u zgjua në mëngjes, Pinoku vuri re se nuk ishte më prej druri. Ishte një djalë i vërtetë, me lëkurë të ngrohtë, me flokë kafe e me sy të qeshur.$s$,
    $s$Xhepeto ishte shëruar dhe po gdhendte në punishte, i gëzuar si dikur. Dhe në një cep të dhomës, i mbështetur pas karriges, ishte kukulla e vjetër prej druri, me kokën anash e me hundën e gjatë. «Sa qesharak isha kur isha kukull!» tha Pinoku, duke qeshur. «Dhe sa i lumtur jam tani që jam bërë djalë i mirë!»$s$
  ]::text[],
  array['classic', 'lessons', 'adventure']::text[], 48, 120, 14, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gpinoku" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#F0E0CE"/><stop offset="1" stop-color="#F8EEE3"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gpinoku)"/><rect x="14" y="14" width="34" height="40" rx="3" fill="#2E5566"/><path d="M24 23Q24 26 27 26Q24 26 24 29Q24 26 21 26Q24 26 24 23Z" fill="#F3EBD9"/><circle cx="38" cy="24" r="5" fill="#F3EBD9"/><path d="M31 14V54M14 34H48" fill="none" stroke="#F0E0CE" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><rect x="124" y="22" width="18" height="14" rx="1.5" fill="#E7D2BC"/><rect x="127" y="25" width="12" height="8" rx="1" fill="#A6CDB4"/><rect x="0" y="92" width="160" height="28" rx="0" fill="#DCC3A8"/><ellipse cx="80" cy="104" rx="50" ry="8" fill="#E7D2BC"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 35) scale(1.15)"><circle cx="32" cy="18" r="8" fill="#E8C9A0"/><path d="M38 18L52 16L38 20Z" fill="#E8C9A0"/><path d="M22 12Q32 0 42 12Z" fill="#D9644A"/><rect x="26" y="26" width="12" height="18" rx="2" fill="#D9644A"/><path d="M26 30L18 40M38 30L46 40M29 44L27 58M35 44L37 58" fill="none" stroke="#E8C9A0" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><circle cx="30" cy="17" r="1" fill="#8A5A44"/><path d="M28 22Q31 24 34 22" fill="none" stroke="#8A5A44" stroke-width="1" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
